import React, { useState } from 'react';

function CurationSection() {
  const [activeIdx, setActiveIdx] = useState(0);

  // 💡 [데이터 구조] 큐레이션 영화 목록 데이터
  const curationList = [
    {
      id: 1,
      badge: "MEGABOX FILM SOCIETY",
      title: "싱 어 게인",
      description: "팝스타의 꿈은 접었지만 음악안에 놓지 못한 무명 축가 가수, 릭.\n한땐 잘나갔지만 지금은 나락 직전의 팝스타, 대니.\n우연히 만난 두 사람, 그들이 완성한 단 하나의 노래.\n하지만 그 곡은 오직 대니의 이름으로만 세상에 알려지는데-",
      // 👉 [주석] 좌측 메인 포스터 이미지 경로 (예: "/img/curation/main1.jpg")
      mainPoster: "",
      subItems: [
        { id: 101, title: "아가씨", image: "" },
        { id: 102, title: "퍼펙트 블루", image: "" },
        { id: 103, title: "[2026 NT Live] 인간 증오", image: "" },
        { id: 104, title: "청년 조용기: 산을 제주하…", image: "" }
      ]
    },
    {
      id: 2,
      badge: "MEGABOX CLASSIC SOCIETY",
      title: "오페라의 유령",
      description: "오페라 하우스의 지하에 숨어 사는 천재 음악가와\n순수한 프리마돈나를 향한 딜레마와 거부할 수 없는 매혹의 이야기.",
      mainPoster: "",
      subItems: [
        { id: 201, title: "작은 아씨들", image: "" },
        { id: 202, title: "라 트라비아타", image: "" },
        { id: 203, title: "백조의 호수", image: "" },
        { id: 204, title: "지젤", image: "" }
      ]
    }
  ];

  const currentItem = curationList[activeIdx];

  return (
    <section className="w-full bg-[#fbfbfa] pt-16 pb-16 flex flex-col items-center relative overflow-hidden">
      
      <div className="w-full max-w-5xl px-6">
        
        {/* 상단 타이틀 및 '큐레이션 더보기 +' */}
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-xl font-black text-zinc-900 tracking-tight">큐레이션</h2>
          <button className="text-xs font-bold text-zinc-500 hover:text-black">
            큐레이션 더보기 +
          </button>
        </div>

        {/* 큐레이션 메인 콘텐츠 박스 */}
        <div className="bg-white rounded-3xl p-8 md:p-12 shadow-2xl border border-zinc-100 flex flex-col lg:flex-row gap-10 items-center">
          
          {/* [좌측] 메인 포스터 및 상세정보/예매 버튼 */}
          <div className="w-full lg:w-5/12 flex flex-col items-center">
            
            {/* 💡 [주석: 좌측 메인 영화 포스터 이미지 공간] */}
            <div className="relative w-full h-[400px] rounded-2xl overflow-hidden shadow-lg bg-zinc-100 flex items-center justify-center mb-6 border border-zinc-200">
              {currentItem.mainPoster ? (
                <img src={currentItem.mainPoster} alt={currentItem.title} className="w-full h-full object-cover" />
              ) : (
                <div className="text-center p-4">
                  <span className="text-xs font-bold text-zinc-400 block mb-1">메인 포스터 이미지 공간</span>
                  <span className="text-[10px] text-zinc-300">({currentItem.title})</span>
                </div>
              )}
            </div>

            {/* 상세정보 / 예매 버튼 */}
            <div className="w-full grid grid-cols-2 gap-3">
              <button className="py-3 rounded-xl bg-zinc-900 text-white font-bold text-xs hover:bg-zinc-800 transition">
                상세정보
              </button>
              <button className="py-3 rounded-xl bg-[#00A086] text-white font-bold text-xs hover:bg-[#008771] transition">
                예매
              </button>
            </div>

          </div>

          {/* [우측] 정보 텍스트 및 우측 서브 썸네일 리스트 */}
          <div className="w-full lg:w-7/12 flex flex-col justify-between space-y-6">
            
            {/* 상단 텍스트 정보 */}
            <div>
              <span className="text-[10px] font-extrabold text-[#503396] bg-purple-50 px-2.5 py-1 rounded-md inline-block mb-3">
                {currentItem.badge}
              </span>
              <h3 className="text-3xl font-black text-zinc-900 tracking-tight mb-4">
                {currentItem.title}
              </h3>
              <p className="text-xs text-zinc-600 font-medium leading-relaxed whitespace-pre-line">
                {currentItem.description}
              </p>
            </div>

            {/* 하단 가로형 서브 썸네일 리스트 */}
            <div className="pt-4 border-t border-zinc-100">
              <div className="grid grid-cols-4 gap-3">
                {currentItem.subItems.map((sub, idx) => (
                  <div key={sub.id} className="flex flex-col gap-2 cursor-pointer group">
                    
                    {/* 💡 [주석: 우측 서브 영화 썸네일 이미지 공간] */}
                    <div className="w-full h-28 rounded-xl bg-zinc-100 overflow-hidden shadow border border-zinc-200 flex items-center justify-center">
                      {sub.image ? (
                        <img src={sub.image} alt={sub.title} className="w-full h-full object-cover group-hover:scale-105 transition duration-300" />
                      ) : (
                        <span className="text-[9px] text-zinc-400 text-center px-1">썸네일 이미지</span>
                      )}
                    </div>

                    <span className="text-[10px] font-bold text-zinc-800 truncate text-center group-hover:text-[#503396]">
                      {sub.title}
                    </span>

                  </div>
                ))}
              </div>
            </div>

          </div>

        </div>

      </div>

    </section>
  );
}

export default CurationSection;
